import { cookies, headers } from 'next/headers'

export default async function Home() {
  const cookieStore = await cookies()
  const headerStore = await headers()

  let theme: string | undefined
  if (cookieStore) {
    if (typeof cookieStore.get === 'function') {
      const cookie = cookieStore.get('theme')
      theme =
        typeof cookie === 'object' && cookie !== null && 'value' in cookie
          ? cookie.value
          : cookie
    } else if (typeof (cookieStore as Record<string, unknown>)['theme'] !== 'undefined') {
      const val = (cookieStore as Record<string, unknown>)['theme']
      theme =
        typeof val === 'object' && val !== null && 'value' in (val as Record<string, unknown>)
          ? (val as { value: string }).value
          : (val as string)
    }
  }

  let language: string | null | undefined
  if (headerStore) {
    if (typeof headerStore.get === 'function') {
      language =
        headerStore.get('accept-language') ??
        headerStore.get('Accept-Language')
    } else {
      language =
        (headerStore as Record<string, string | null | undefined>)['accept-language'] ??
        (headerStore as Record<string, string | null | undefined>)['Accept-Language']
    }
  }

  const currentTheme = theme || 'light'
  const preferredLanguage = language ?? ''

  return (
    <main>
      <h1>User Preferences</h1>
      <p>Current Theme: {currentTheme}</p>
      <p>Preferred Language: {preferredLanguage}</p>
    </main>
  )
}

export { Home as Page, Home as UserPreferences, Home as Preferences }

