import { describe, it, expect, vi } from 'vitest'
import Home from './app/page'
import { renderToStaticMarkup } from 'react-dom/server'
import { cookies, headers } from 'next/headers'

vi.mock('next/headers', () => ({
  cookies: vi.fn(),
  headers: vi.fn(),
}))

describe('Theme and Language preferences server component', () => {
  it('reads theme cookie and displays current theme preference', async () => {
    vi.mocked(cookies).mockResolvedValue({
      get: (name: string) => (name === 'theme' ? { name: 'theme', value: 'dark' } : undefined),
    } as any)
    vi.mocked(headers).mockResolvedValue({
      get: (name: string) => (name === 'accept-language' ? 'en-US' : null),
    } as any)

    const jsx = await Home()
    const html = renderToStaticMarkup(jsx)
    expect(html).toContain('dark')
    expect(html).toContain('en-US')
  })

  it('defaults to light if no theme cookie exists', async () => {
    vi.mocked(cookies).mockResolvedValue({
      get: () => undefined,
    } as any)
    vi.mocked(headers).mockResolvedValue({
      get: (name: string) => (name === 'accept-language' ? 'fr-FR' : null),
    } as any)

    const jsx = await Home()
    const html = renderToStaticMarkup(jsx)
    expect(html).toContain('light')
    expect(html).toContain('fr-FR')
  })

  it('handles synchronous mock for cookies and headers', async () => {
    vi.mocked(cookies).mockReturnValue({
      get: (name: string) => (name === 'theme' ? { value: 'custom-theme' } : undefined),
    } as any)
    vi.mocked(headers).mockReturnValue({
      get: (name: string) => (name === 'accept-language' ? 'de-DE' : null),
    } as any)

    const jsx = await Home()
    const html = renderToStaticMarkup(jsx)
    expect(html).toContain('custom-theme')
    expect(html).toContain('de-DE')
  })
})
